def summarize(rows, accounts):
    aggregates = {account: [0, 0] for account in accounts}
    if not aggregates:
        return []

    for row in rows:
        aggregate = aggregates.get(row["account"])
        if aggregate is not None:
            aggregate[0] += 1
            aggregate[1] += row["delta"]

    return [
        {"account": account,
         "count": aggregates[account][0],
         "total": aggregates[account][1]}
        for account in accounts
    ]

